SELECT CASE WHEN discount_pct >= 0.27 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, ROUND(AVG(discount_pct), 2) AS avg_discount_pct, ROUND(AVG(discount_pct), 2) AS avg_discount_pct_2, SUM(CASE WHEN channel = 'web' THEN discount_pct ELSE 0 END) AS web_discount_pct FROM promotions GROUP BY CASE WHEN discount_pct >= 0.27 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING avg_discount_pct_2 > 0
